import { Router, type Request, type Response, type NextFunction } from 'express';
import { signJwt } from './lib/jwt.ts';
import { getUser, requireAuth } from './middleware/auth.ts';
import { checkRateLimit } from './rate-limit.ts';
import { findUserByEmail, listInvoices, listSubscriptions, toSubscriptionResponse } from './store.ts';

export const router = Router();

router.post('/login', (req: Request, res: Response) => {
  const { email, password } = req.body as { email?: string; password?: string };
  const user = email ? findUserByEmail(email) : undefined;
  if (!user || user.password !== password) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }
  return res.json({ token: signJwt({ sub: user.id, role: user.role }) });
});

router.get('/me', requireAuth, (req: Request, res: Response) => {
  const user = getUser(req);
  return res.json({ id: user.sub, role: user.role });
});

router.get('/subscriptions', requireAuth, (req: Request, res: Response) => {
  const user = getUser(req);
  if (!checkRateLimit(user.sub, 'read')) return res.status(429).json({ error: 'Too many requests' });
  return res.json(listSubscriptions(user.sub).map((entry) => toSubscriptionResponse(entry)));
});

router.get('/invoices', requireAuth, (req: Request, res: Response) => {
  const user = getUser(req);
  if (!checkRateLimit(user.sub, 'read')) return res.status(429).json({ error: 'Too many requests' });
  return res.json(listInvoices(user.sub));
});

router.post('/subscriptions/:id/cancel', requireAuth, (req: Request, res: Response, next: NextFunction) => {
  const user = getUser(req);
  if (!checkRateLimit(user.sub, 'write')) return res.status(429).json({ error: 'Too many requests' });
  const subscription = listSubscriptions(user.sub).find((entry) => entry.id === req.params.id);
  if (!subscription) return next();
  // The plan is paid through `renewsAt`, so it keeps running until then and simply does not renew.
  subscription.cancelAtPeriodEnd = true;
  return res.json(toSubscriptionResponse(subscription));
});

