export interface User {
  id: string;
  email: string;
  password: string;
  role: 'admin' | 'member' | 'viewer';
}

export interface Subscription {
  id: string;
  userId: string;
  plan: 'starter' | 'team' | 'enterprise';
  status: 'active' | 'past_due' | 'cancelled';
  renewsAt: string;
  /** Set by a cancellation: the plan runs to `renewsAt`, then does not renew. */
  cancelAtPeriodEnd: boolean;
}

export interface Invoice {
  id: string;
  userId: string;
  amountCents: number;
  issuedAt: string;
  paid: boolean;
}

const users: User[] = [
  { id: 'u_1001', email: 'ada@example.com', password: 'correct horse battery staple', role: 'admin' },
  { id: 'u_1002', email: 'bea@example.com', password: 'hunter2', role: 'member' },
];

const subscriptions: Subscription[] = [
  { id: 'sub_501', userId: 'u_1001', plan: 'team', status: 'active', renewsAt: '2026-10-01', cancelAtPeriodEnd: false },
  { id: 'sub_502', userId: 'u_1002', plan: 'starter', status: 'past_due', renewsAt: '2026-09-14', cancelAtPeriodEnd: false },
];

const invoices: Invoice[] = [
  { id: 'inv_9001', userId: 'u_1001', amountCents: 4900, issuedAt: '2026-08-01', paid: true },
  { id: 'inv_9002', userId: 'u_1001', amountCents: 4900, issuedAt: '2026-09-01', paid: false },
  { id: 'inv_9003', userId: 'u_1002', amountCents: 1900, issuedAt: '2026-09-01', paid: false },
];

export function findUserByEmail(email: string): User | undefined {
  return users.find((user) => user.email.toLowerCase() === email.toLowerCase());
}

export function listSubscriptions(userId: string): Subscription[] {
  return subscriptions.filter((subscription) => subscription.userId === userId);
}

/**
 * The status a client should see. A subscription cancelled mid-period keeps its stored status
 * until `renewsAt` arrives, and reads as cancelled from that moment on.
 */
export function effectiveStatus(subscription: Subscription, now = Date.now()): Subscription['status'] {
  if (!subscription.cancelAtPeriodEnd) return subscription.status;
  return now >= Date.parse(subscription.renewsAt) ? 'cancelled' : subscription.status;
}

/** A subscription as sent to clients, with `status` resolved by {@link effectiveStatus}. */
export function toSubscriptionResponse(subscription: Subscription, now = Date.now()): Subscription {
  return { ...subscription, status: effectiveStatus(subscription, now) };
}

export function listInvoices(userId: string): Invoice[] {
  return invoices.filter((invoice) => invoice.userId === userId);
}

import { describe, expect, it } from 'vitest';
import { effectiveStatus, type Subscription } from '../server/store.ts';

const base: Subscription = {
  id: 'sub_1',
  userId: 'u_1',
  plan: 'team',
  status: 'active',
  renewsAt: '2026-10-01',
  cancelAtPeriodEnd: false,
};

const beforeRenewal = Date.parse('2026-09-20');
const afterRenewal = Date.parse('2026-10-02');

describe('effectiveStatus', () => {
  it('keeps a cancelled plan active until the renewal date', () => {
    const cancelled = { ...base, cancelAtPeriodEnd: true };
    expect(effectiveStatus(cancelled, beforeRenewal)).toBe('active');
  });

  it('reads as cancelled once the renewal date has passed', () => {
    const cancelled = { ...base, cancelAtPeriodEnd: true };
    expect(effectiveStatus(cancelled, afterRenewal)).toBe('cancelled');
  });

  it('cancels exactly at the renewal instant', () => {
    const cancelled = { ...base, cancelAtPeriodEnd: true };
    expect(effectiveStatus(cancelled, Date.parse('2026-10-01'))).toBe('cancelled');
  });

  it('leaves an uncancelled plan alone after the renewal date', () => {
    expect(effectiveStatus(base, afterRenewal)).toBe('active');
  });

  it('preserves a past_due plan until its renewal date', () => {
    const pastDue: Subscription = { ...base, status: 'past_due', cancelAtPeriodEnd: true };
    expect(effectiveStatus(pastDue, beforeRenewal)).toBe('past_due');
    expect(effectiveStatus(pastDue, afterRenewal)).toBe('cancelled');
  });
});
